ALTER TABLE public.clinical_cases DROP CONSTRAINT clinical_cases_exam_mode_check;
ALTER TABLE public.clinical_cases ADD CONSTRAINT clinical_cases_exam_mode_check CHECK (exam_mode IN ('oral_board','panel_exam','preparation'));
DO $backfill$
DECLARE c jsonb; cid uuid; items jsonb; public_items jsonb; answers text; idx integer; labels text[]; a text[]; invasive boolean; card_title text;
BEGIN
labels := ARRAY['Menyapa dan memperkenalkan diri sebagai dokter. SKOR: 1 = menyapa dan mengenalkan diri; 0 = tidak.','Menjelaskan prosedur dan indikasi dengan bahasa awam. SKOR: 2 = tindakan dan tujuan jelas; 1 = salah satu; 0 = tidak.','Menilai kontraindikasi atau kondisi khusus sebelum mulai. SKOR: 2 = kondisi relevan dan penyesuaian; 1 = sebagian; 0 = tidak.','Menjelaskan risiko/ketidaknyamanan yang relevan dan proporsional. SKOR: 2 = risiko utama disebut; 1 = sebagian; 0 = tidak.','Meminta persetujuan dan memverifikasi nama serta tanggal lahir, menunggu jawaban; pada anak melibatkan wali. SKOR: 2 = persetujuan dan identitas; 1 = salah satu; 0 = tidak.','Mempersiapkan pasien: posisi, privasi dan keselamatan sebelum tindakan. SKOR: 2 = persiapan utama tepat; 1 = sebagian; 0 = tidak.','Menyebut alat utama dan memastikan kelayakannya. SKOR: 2 = alat utama sesuai; 1 = sebagian; 0 = tidak.','Membersihkan tangan dan memakai APD sesuai risiko pajanan. SKOR: 2 = keduanya; 1 = salah satu; 0 = tidak.','Menyiapkan asepsis dan sarung tangan steril untuk tindakan steril. SKOR: 2 = keduanya; 1 = salah satu; 0 = tidak.'];
FOR c IN SELECT value FROM jsonb_array_elements($cards$[
["Bubble test","ekokardiografi",true,"Saya akan USG jantung sambil menyuntik cairan bergelembung kecil untuk mencari jalur bocor antarruang jantung.","Kehamilan atau pirau kanan-kiri besar perlu penilaian dahulu.","Risiko memar, infeksi dan sangat jarang gangguan saraf.","Miring kiri; cek akses vena.","Mesin echo, spuit, stopcock, saline dan monitor."],
["Katup prostetik aorta","ekokardiografi",false,"Saya akan USG jantung untuk melihat apakah katup buatan membuka baik atau bocor.","Pemeriksaan lewat dada umumnya aman; bila luka dada, kita sesuaikan posisi.","Mungkin terasa sedikit tertekan.","Miring kiri.","Echo, probe, gel, EKG dan data jenis katup."],
["Katup prostetik mitral / DVR","ekokardiografi",false,"Saya akan USG jantung untuk memeriksa gerakan dan aliran melalui katup buatan, apakah menyempit atau bocor.","Pemeriksaan umumnya aman; luka dada perlu penyesuaian.","Gel terasa dingin.","Miring kiri.","Echo, probe, gel, EKG dan data prostesis."],
["Fungsi diastolik LV","ekokardiografi",false,"Saya akan USG jantung untuk menilai kemampuan jantung mengisi darah dan apakah tekanannya meningkat.","Umumnya aman, posisi disesuaikan bila sesak atau luka dada.","Tekanan probe mungkin kurang nyaman.","Miring kiri; catat tinggi, berat, pasang EKG.","Echo, probe dan gel."],
["Fungsi sistolik RV / LV","ekokardiografi",false,"Saya akan USG untuk menilai kekuatan pompa jantung.","Tidak menggunakan radiasi; bila sesak atau luka dada, posisi disesuaikan.","Tekanan alat bisa sedikit tidak nyaman.","Miring kiri.","Echo, probe, gel dan EKG."],
["Regional wall motion assessment","ekokardiografi",false,"Saya akan USG jantung untuk melihat apakah ada bagian otot jantung yang kurang bergerak akibat gangguan aliran darah.","Umumnya aman; posisi disesuaikan bila sesak atau nyeri.","Gel terasa dingin.","Miring kiri.","Echo, probe, gel dan EKG."],
["Akses arteri radial / femoral (termasuk post-CABG)","intervensi",true,"Saya akan memasukkan selang kecil melalui pembuluh nadi untuk pemeriksaan jantung.","Pembuluh tersumbat atau infeksi setempat perlu akses lain.","Risiko memar, perdarahan, infeksi, cedera atau sumbatan pembuluh.","Baringkan; cek perfusi dan risiko perdarahan.","Set pungsi steril, USG, anestesi lokal dan monitor."],
["Coronary angiography / kanulasi LCA-RCA / graft","intervensi",true,"Saya akan memeriksa pembuluh jantung dengan selang kecil dan kontras untuk melihat penyempitan pembuluh atau graft.","Alergi, gangguan ginjal atau perdarahan perlu penilaian.","Risiko memar, perdarahan, infeksi, cedera pembuluh, gangguan ginjal, alergi, serangan jantung atau stroke.","Baringkan; cek akses, persetujuan dan monitor.","Kateter, kontras dan set steril."],
["Proteksi radiasi pasien, operator dan tim","intervensi",false,"Pemeriksaan memakai sinar X agar pembuluh terlihat; kami akan membatasi paparan tanpa mengganggu pemeriksaan.","Kehamilan perlu penilaian manfaat dan risiko.","Paparan berlebih dapat merugikan jaringan.","Verifikasi kehamilan bila relevan.","Pelindung tim, dosimeter, perisai; atur proteksi pasien sesuai protokol."],
["Ankle-brachial index (ABI)","vaskular",false,"Saya akan membandingkan tekanan darah lengan dan kaki untuk menilai aliran darah ke kaki.","Luka, nyeri berat atau akses pembuluh perlu penyesuaian manset.","Manset dapat terasa ketat.","Telentang istirahat.","Manset sesuai ukuran, Doppler dan gel."],
["Pemeriksaan fisik ALI dan PAD","vaskular",false,"Saya akan melihat, meraba nadi dan menilai rasa serta gerak kaki untuk mengetahui aliran darahnya.","Bila sangat nyeri, pemeriksaan dilakukan perlahan tanpa menunda penanganan keadaan akut.","Mungkin terasa tidak nyaman.","Telentang; buka kedua tungkai dengan privasi.","Doppler dan stetoskop."],
["DUS vena - DVT","vaskular",false,"Saya akan USG pembuluh balik kaki untuk mencari bekuan darah.","Luka atau nyeri hebat perlu penyesuaian.","Probe dapat terasa menekan.","Posisikan sesuai segmen; hindari pijatan kuat.","Probe linear, gel dan Doppler."],
["DUS vena - CVI/refluks","vaskular",false,"Saya akan USG pembuluh balik untuk menilai apakah darah mengalir balik akibat katup yang lemah.","Bila sulit berdiri kita sesuaikan posisi.","Probe dapat menimbulkan rasa tidak nyaman.","Berdiri dengan penyangga atau posisi alternatif.","Probe linear, gel dan Doppler."],
["DUS carotis","vaskular",false,"Saya akan USG pembuluh leher untuk melihat penyempitan yang dapat memicu stroke.","Luka atau nyeri leher perlu penyesuaian.","Tekanan ringan alat mungkin kurang nyaman.","Telentang, kepala sedikit menoleh.","Probe linear, gel dan Doppler."],
["DUS arteri dan vena ekstremitas superior","vaskular",false,"Saya akan USG pembuluh lengan untuk menilai aliran, penyumbatan atau kelainan pembuluh.","Luka atau nyeri memerlukan penyesuaian tekanan probe.","Pemeriksaan umumnya aman; mungkin terasa tekanan ringan.","Baringkan dengan lengan ditopang.","Probe linear, gel dan Doppler."],
["DUS pseudoaneurisma pascapungsi","vaskular",false,"Saya akan USG benjolan untuk mencari kebocoran pembuluh akibat tusukan sebelumnya.","Nyeri berat atau perdarahan aktif memerlukan stabilisasi dahulu.","Tekanan alat bisa tidak nyaman.","Baringkan; cek perfusi, ukuran benjolan; jangan menekan kuat.","Probe linear dan gel."],
["Echo aortic root / STJ / sinus Valsalva","vaskular",false,"Saya akan USG jantung untuk melihat pelebaran pembuluh utama dan tanda robekan.","Bila kondisi tidak stabil, penanganan segera diutamakan.","Probe mungkin sedikit menekan.","Posisi sesuai stabilitas.","Echo, probe, gel dan monitor."],
["Evaluasi akses pre-CAG / Allen test bila diminta","vaskular",false,"Saya akan menilai nadi dan aliran darah tangan sebelum tindakan pembuluh.","Luka atau nyeri berat perlu penyesuaian; tidak mengulang Allen test bila penguji mengecualikannya.","Saat pembuluh ditekan sebentar tangan mungkin terasa tidak nyaman.","Lengan ditopang; nilai perfusi.","Oksimeter atau Doppler sesuai kebutuhan."],
["Echo hemodinamik","iacc",false,"Saya akan USG jantung dan pembuluh besar untuk menilai pompa, aliran darah dan kebutuhan cairan.","Posisi disesuaikan dengan kondisi dan stabilitas pasien.","Mungkin terasa sedikit tertekan.","Posisi nyaman.","Echo, probe, gel, EKG dan monitor tekanan darah."],
["Passive leg raising (PLR)","iacc",false,"Saya akan mengangkat kaki sementara untuk melihat respons aliran darah terhadap tambahan volume.","Cedera tulang belakang, panggul atau kaki perlu penilaian.","Posisi mungkin menambah sesak atau nyeri.","Monitor pasien; siapkan perubahan posisi dari setengah duduk.","Ranjang yang bisa diatur dan echo untuk mengukur aliran."],
["Lung ultrasound","iacc",false,"Saya akan USG dada untuk mencari cairan atau gangguan paru penyebab sesak.","Luka atau sesak berat memerlukan penyesuaian posisi.","Gel terasa dingin.","Posisi sesuai toleransi.","Probe, gel dan oksimeter."],
["NIV CPAP/BiPAP","iacc",false,"Saya akan memasang masker bertekanan untuk membantu napas.","Muntah, tidak mampu menjaga jalan napas atau sangat tidak stabil membuat cara ini tidak aman.","Risiko iritasi kulit, kebocoran, aspirasi dan tekanan darah turun.","Dudukkan pasien; monitor kondisi.","Mesin, masker, oksigen, monitor, suction dan cadangan intubasi."],
["Endotracheal intubation","iacc",false,"Kami akan memasukkan selang napas karena napas tidak mencukupi.","Cedera leher atau sumbatan perlu pendekatan khusus.","Risiko cedera gigi, perdarahan, aspirasi, kekurangan oksigen, tekanan darah turun hingga henti jantung.","Panggil tim; monitor, posisi dan oksigenasi.","Alat intubasi, suction, kapnografi dan alat cadangan."],
["Simulasi tatalaksana ALO","iacc",false,"Kami akan membantu napas dan memberikan obat untuk mengurangi cairan paru.","Obat disesuaikan dengan tekanan darah, ginjal dan alergi.","Risiko tekanan darah turun, gangguan garam darah atau iritasi masker.","Dudukkan dan monitor.","Oksigen, akses intravena, obat dan alat ventilasi sesuai indikasi."],
["RLHC / RHC dan uji vasoreaktivitas","pediatri",true,"Kami akan memakai selang kecil untuk mengukur tekanan dan oksigen jantung anak serta respons pembuluh paru.","Infeksi atau gangguan pembekuan perlu penilaian.","Risiko memar, perdarahan, infeksi, gangguan irama, cedera pembuluh atau jantung, serta komplikasi kontras bila digunakan.","Verifikasi wali, berat badan, akses dan monitor.","Kateter, set steril dan alat resusitasi."],
["Sequential segmental analysis / defek septum","pediatri",false,"Saya akan USG jantung anak untuk melihat susunan ruang, pembuluh dan lubang antarruang.","Sesak atau gelisah memerlukan penyesuaian posisi.","Gel terasa dingin.","Libatkan orang tua; posisi nyaman.","Echo, probe sesuai ukuran dan gel."],
["Auskultasi jantung anak","pediatri",false,"Saya akan mendengarkan bunyi jantung anak untuk mencari bunyi tambahan akibat kelainan aliran darah.","Bila anak sesak, posisi disesuaikan.","Stetoskop mungkin terasa dingin.","Tenangkan anak bersama orang tua; buka dada seperlunya.","Stetoskop."],
["Hypercyanotic spell - penanganan awal","pediatri",false,"Anak sedang kekurangan oksigen. Kami akan membantu posisi, napas dan memberi obat sesuai kondisi.","Obat disesuaikan dengan tekanan darah dan berat badan.","Obat mungkin menyebabkan tekanan darah turun atau gangguan napas.","Panggil bantuan; tenangkan anak bersama wali; siapkan posisi knee-chest dan monitor.","Oksigen, obat dan alat resusitasi."],
["Transcutaneous pacing","aritmia",false,"Kami akan memberi rangsangan listrik melalui bantalan dada karena denyut terlalu lambat.","Pada henti jantung utamakan resusitasi jantung paru.","Tindakan dapat nyeri, mengiritasi kulit atau gagal menghasilkan denyut.","Monitor pasien; siapkan lokasi bantalan.","Pacer, defibrilator, obat nyeri bila memungkinkan dan resusitasi."],
["Interogasi permanent pacemaker","aritmia",false,"Saya akan memeriksa alat pacu dengan perangkat pembaca untuk melihat baterai, kabel dan pengaturannya.","Cek ketergantungan alat pacu; perubahan pengaturan harus hati-hati.","Perubahan pengaturan dapat mengganggu denyut atau membuat pusing.","Baringkan dan monitor.","Programmer yang cocok dan EKG."],
["SVT - manuver vagal / terapi awal","aritmia",false,"Saya akan mencoba manuver napas mengejan untuk memperlambat denyut cepat.","Tekanan darah turun atau kondisi tidak stabil memerlukan tindakan lain.","Manuver dapat membuat pusing atau tekanan darah turun sementara.","Baringkan; monitor; cek irama dan kestabilan.","Spuit dan alat resusitasi."],
["Pemeriksaan hipotensi ortostatik","aritmia",false,"Saya akan mengukur tekanan darah saat berbaring dan berdiri untuk mencari penyebab pusing.","Tidak mampu berdiri atau risiko jatuh memerlukan penyesuaian.","Bisa terasa pusing atau hampir pingsan.","Baringkan dahulu; dampingi saat berdiri.","Tensimeter, jam, kursi dan pendamping."],
["Six-minute walk test","rehab_prevensi",false,"Saya akan meminta Bapak/Ibu berjalan enam menit untuk menilai kemampuan aktivitas.","Nyeri dada tidak stabil atau kondisi akut berat harus ditangani dahulu.","Bisa lelah, sesak, pusing atau nyeri dada; hentikan bila muncul gejala berbahaya.","Cek vital awal.","Lintasan, penanda, timer, oksimeter, kursi dan resusitasi."],
["Jugular venous pressure (JVP)","karklin",false,"Saya akan melihat denyut pembuluh leher untuk menilai tekanan darah balik ke jantung.","Nyeri leher atau sesak memerlukan posisi nyaman.","Umumnya aman, tidak ada tusukan.","Setengah duduk; buka leher dengan privasi.","Dua penggaris dan lampu."],
["Hepatojugular reflux (HJR)","karklin",false,"Saya akan menekan perlahan perut untuk melihat respons pembuluh leher terhadap tambahan aliran darah.","Nyeri perut akut atau luka operasi perlu penilaian dahulu.","Tekanan bisa terasa kurang nyaman.","Setengah duduk; lihat vena leher; periksa nyeri perut.","Penggaris dan lampu."],
["EKG standar, kanan dan posterior","karklin",false,"Saya akan memasang elektroda di dada dan anggota tubuh untuk merekam listrik jantung, termasuk sisi kanan atau punggung bila diperlukan.","Luka kulit atau alergi perekat perlu penyesuaian.","Perekat dapat mengiritasi kulit.","Baringkan dengan privasi.","Mesin EKG, kabel, elektroda dan pembersih kulit."],
["Treadmill exercise test (bila diminta melakukan)","tambahan",false,"Saya akan meminta Bapak/Ibu berjalan di alat dengan beban bertahap sambil merekam jantung untuk menilai respons terhadap aktivitas.","Nyeri dada tidak stabil, syok atau gangguan irama berat harus ditangani dahulu.","Risiko sesak, nyeri dada, aritmia atau pingsan.","Cek vital dan EKG.","Treadmill, manset, monitor, defibrilator dan tim."],
["Pericardiocentesis (bila menjadi demonstrasi)","tambahan",true,"Kami akan mengeluarkan cairan yang menekan jantung dengan jarum dan selang.","Gangguan pembekuan perlu penilaian, tetapi keadaan mengancam nyawa membutuhkan tindakan segera.","Risiko perdarahan, infeksi, cedera jantung, paru atau gangguan irama hingga henti jantung.","Panggil tim; monitor.","Echo, set steril, anestesi lokal dan alat resusitasi."],
["Synchronized cardioversion","tambahan",false,"Kami akan memberi kejutan listrik terukur untuk mengembalikan irama jantung.","Risiko bekuan perlu penilaian bila ada fibrilasi atrium, tanpa menunda tindakan darurat.","Risiko nyeri, luka kulit, gangguan irama atau stroke.","Monitor pasien dan siapkan sedasi bila memungkinkan.","Defibrilator, bantalan, oksigen, sedasi dan resusitasi."],
["TEE (bila diminta persiapan)","tambahan",false,"Saya akan USG jantung melalui selang di tenggorokan agar gambar lebih jelas.","Gangguan kerongkongan atau perdarahan perlu penilaian; cek puasa dan riwayat menelan.","Risiko tersedak, aspirasi, perdarahan, cedera kerongkongan dan gangguan napas akibat sedasi.","Cek puasa dan riwayat menelan.","Probe, monitor, suction dan tim."],
["Pemeriksaan tekanan darah / ABPM","tambahan",false,"Saya akan memasang manset untuk mengukur tekanan darah saat aktivitas dan tidur bila memakai alat 24 jam.","Luka, fistula atau gangguan aliran lengan perlu penyesuaian lokasi.","Manset bisa terasa ketat atau mengganggu tidur.","Pilih lengan dan ukuran manset.","Alat, jam dan buku aktivitas."],
["Pengambilan darah / AGD (bila diminta)","tambahan",true,"Saya akan mengambil darah untuk menilai kondisi tubuh; bila dari arteri, kadar oksigen dan keasaman darah.","Infeksi lokasi atau gangguan aliran perlu penilaian.","Risiko nyeri, memar, perdarahan, infeksi dan cedera pembuluh.","Posisikan, cek lokasi dan risiko perdarahan.","Set steril, label dan kasa."],
["Injeksi / akses IV (bila diminta)","tambahan",true,"Saya akan memasang selang kecil pada pembuluh balik untuk memberi obat atau cairan.","Hindari lokasi infeksi atau pembuluh bermasalah; cek alergi.","Risiko nyeri, memar, perdarahan, infeksi dan cairan bocor ke jaringan.","Baringkan; cek alergi.","Kanul, antiseptik, plester, saline dan wadah tajam."],
["Angiografi pulmonal pasca-BCPS / DORV","tambahan",true,"Kami akan melihat pembuluh paru anak memakai selang kecil dan kontras untuk menilai aliran sebelum operasi berikutnya.","Alergi, gangguan ginjal atau perdarahan perlu dinilai.","Risiko perdarahan, memar, infeksi, cedera pembuluh dan gangguan irama.","Cek wali, berat badan, akses dan monitor.","Kateter, kontras, set steril dan resusitasi."],
["CT angiografi aorta / koroner","tambahan",false,"Saya akan memindai pembuluh dengan sinar X dan zat kontras untuk melihat penyempitan atau robekan.","Alergi, gangguan ginjal atau kehamilan perlu penilaian.","Risiko alergi, gangguan ginjal, bocor kontras dan radiasi.","Cek fungsi ginjal, akses vena dan alergi.","Pemindai, kontras dan monitor."],
["CMR / uji fibrosis dan viabilitas","tambahan",false,"Saya akan memindai jantung dengan magnet untuk menilai jaringan dan fungsi jantung.","Implan logam dan gangguan ginjal bila memakai kontras perlu diperiksa.","Mungkin terasa sempit, bising atau jarang alergi kontras.","Cek perangkat implan, lepaskan logam.","Pemindai, pelindung telinga dan monitor kompatibel."],
["Holter monitoring","tambahan",false,"Saya akan merekam denyut jantung selama beraktivitas untuk mencari gangguan irama yang hilang timbul.","Luka atau alergi perekat memerlukan penyesuaian.","Kulit bisa terasa gatal.","Bersihkan kulit dengan privasi.","Elektroda, perekam, baterai dan buku gejala."],
["Pemeriksaan fisis kardiovaskular terarah","tambahan",false,"Saya akan memeriksa nadi, tekanan darah, bunyi jantung dan paru untuk mengetahui penyebab keluhan.","Nyeri atau sesak memerlukan penyesuaian posisi.","Umumnya aman; sentuhan alat mungkin tidak nyaman.","Posisi nyaman, jaga privasi.","Tensimeter, stetoskop, oksimeter dan jam."]
]$cards$::jsonb) LOOP
  idx := coalesce(idx,0)+1;
  card_title := 'Persiapan ' || lpad(idx::text,2,'0') || ' – ' || (c->>0);
  IF EXISTS (SELECT 1 FROM public.clinical_cases WHERE exam_mode='preparation' AND clinical_cases.title=card_title) THEN CONTINUE; END IF;
  cid := gen_random_uuid(); invasive := (c->>2)::boolean;
  a := ARRAY['Selamat pagi, saya dokter yang akan memeriksa Bapak/Ibu.',c->>3,c->>4,c->>5,'Boleh saya lakukan? Mohon sebutkan nama dan tanggal lahir. Saya menunggu persetujuan; untuk anak saya juga meminta persetujuan wali.',(c->>6)||' Saya menjaga privasi dan menilai keselamatan pasien.', 'Saya menyiapkan '||(c->>7)||' Saya memastikan alat berfungsi.', 'Saya membersihkan tangan enam langkah dan memakai APD sesuai risiko.', 'Saya menyiapkan teknik aseptik dan sarung tangan steril.'];
  SELECT jsonb_agg(jsonb_build_object('id',md5('persiapan-'||idx||'-'||n)::uuid,'text',labels[n],'points',CASE WHEN n=1 THEN 1 ELSE 2 END,'isCritical',n=5 OR n=9,'answer',a[n]) ORDER BY n) INTO items FROM generate_series(1,CASE WHEN invasive THEN 9 ELSE 8 END) n;
  SELECT jsonb_agg(value-'answer' ORDER BY ord) INTO public_items FROM jsonb_array_elements(items) WITH ORDINALITY AS e(value,ord);
  answers := array_to_string(a[1:CASE WHEN invasive THEN 9 ELSE 8 END],E'\n');
  INSERT INTO public.clinical_cases (id,title,exam_mode,initial_prompt,questions_text,checklist_rubric,reading_time_seconds,time_limit_seconds,show_results_to_candidate,status,source,rubric_mode,category)
  VALUES(cid,card_title,'preparation','','Lafalkan persiapan untuk melakukan '||(c->>0)||'. Mulai dari menyapa pasien hingga berhenti tepat sebelum prosedur dimulai.',jsonb_build_object('enabled',true,'items',public_items),10,60,true,'published','admin','checklist',c->>1);
  INSERT INTO public.case_answer_keys(case_id,answer_key_text,checklist_rubric) VALUES(cid,answers,jsonb_build_object('enabled',true,'items',items));
END LOOP;
IF idx <> 48 THEN RAISE EXCEPTION 'Jumlah kartu tidak sesuai: %', idx; END IF;
END;
$backfill$;